                                content
                                    .findFields("ixs_esu,nazev,ixs_hci_dukz,ixs_hci_frmk,ixs_hci_typv,typ_kur,priz_predeu,rozsah_dny,rozsah_hod")
                                    .gfield("model", "collect", content.DtoKurz);
                                if (content.DtoKurz.stav == null)
                                    content.DtoKurz.stav = 10;
                                let jeZmenaNakladu = false;
                                //DtoTurnus
                                if (content.DtoTurnus.stav == null)
                                    content.DtoTurnus.stav = 10;
                                content.DtoTurnus.prubeh = 30;
