                                if (content.DtoKurz.ixs_esu !== content.DtoTurnus.ixs_esu_org)
                                    content.DtoTurnus.ixs_esu_org = content.DtoKurz.ixs_esu;
                                const rbChecked = content.findFields("cena_tur").gfield("getValue");
                                const castkaCelk = content.findFields("c_celk").gfield("getValue");
                                const castkaOso = content.findFields("c_jed").gfield("getValue");
                                if (rbChecked === 1) {
                                    //celkem
                                    jeZmenaNakladu = !parseDecimal(content.DtoTurnus.c_celk).eq(castkaCelk) || !parseDecimal(content.DtoTurnus.c_jed).eq(0);
                                    content.DtoTurnus.c_celk = castkaCelk;
                                    content.DtoTurnus.c_jed = new Decimal(0);
                                }
                                else {
                                    //za osobu
                                    jeZmenaNakladu = !parseDecimal(content.DtoTurnus.c_jed).eq(castkaCelk) || !parseDecimal(content.DtoTurnus.c_celk).eq(0);
                                    content.DtoTurnus.c_jed = castkaOso;
                                    content.DtoTurnus.c_celk = new Decimal(0);
                                }
                                //osoby
                                const view_oso = content.grid_oso.ggrid("getView");
