                                    const pocetDnuSkoleni = (content.DtoKurz.rozsah_dny == null ? new Decimal(0) : parseDecimal(content.DtoKurz.rozsah_dny)).plus(content.DtoKurz.rozsah_hod == null ? 0 : parseDecimal(content.DtoKurz.rozsah_hod).div(8));
                                    const pocetOsob = view_oso.getDataRows(false, "data").filter((r) => r.aktivita === 100).length;
