                                        Gordic.Per.WebControls.showSucess(content, "jres:34921060", "jres:34921061"); //RC 34921060 : Ukládání vzdělávácí akce, RC 34921061 : Uloženo.
                                        content.DtoKurz = result.kurz;
                                        content.DtoTurnus = result.turnus;
                                        //Content.actions.act_Reload?.run();
