                setPocetOpakovani() {
                    const content = this;
                    const checkbox = content.findFields("opakovani").gfield("getValue");
                    const mesice = content.findFields("mesice").gfield("getValue");
                    const roky = content.findFields("roky").gfield("getValue");
                    const datum = content.findFields("dat_opak").gfield("getValue");
                    const field = content.findFields("poc_opak");
                    if (!checkbox || datum == null || ((mesice == null || mesice === 0) && (roky == null || roky === 0))) {
                        field.gfield("clear");
                    }
                    else {
                        const dat_od = content.findFields("dat_splnit_od").gfield("getValue") ?? new Date();
                        const pocetMesicu = (roky == null ? 0 : roky * 12) + (mesice == null ? 0 : mesice);
                        const maxDate = new Date();
                        maxDate.setFullYear(maxDate.getFullYear() + 70);
                        let pocetOpak = 0;
                        dat_od.setMonth(dat_od.getMonth() + pocetMesicu);
                        while (dat_od.getTime() <= datum.getTime() &&
                            dat_od.getTime() < maxDate.getTime()) {
                            dat_od.setMonth(dat_od.getMonth() + pocetMesicu);
                            pocetOpak++;
                        }
                        field.gfield("setValue", pocetOpak);
                    }
                }
