                    content.setAktDetail(content.DtoPozadavku.typ_kv_predp == null ? 0 : content.DtoPozadavku.typ_kv_predp);
                    content.getDetailPozadavku().loadData();
                    content.setDisabled();
                    content.updateSaveButton();
